export interface BatchSources<K, V, E, R> {
  readonly primary: (
    keys: ReadonlyArray<K>
  ) => Effect.Effect<ReadonlyMap<K, V>, E, R>
  readonly replica: (
    keys: ReadonlyArray<K>
  ) => Effect.Effect<ReadonlyMap<K, V>, E, R>
}

export const loadBatch = <K, V, E, R>(
  sources: BatchSources<K, V, E, R>,
  keys: ReadonlyArray<K>
): Effect.Effect<ReadonlyMap<K, V>, E, R> =>
  Effect.catch(sources.primary(keys), () => sources.replica(keys))

export const loadOne = <K, V, E, R>(
  sources: BatchSources<K, V, E, R>,
  key: K
): Effect.Effect<V | undefined, E, R> =>
  Effect.map(loadBatch(sources, [key]), (values) => values.get(key))

export const loadRequired = <K, V, E, R>(
  sources: BatchSources<K, V, E, R>,
  keys: ReadonlyArray<K>,
  onMissing: (key: K) => E
): Effect.Effect<ReadonlyArray<V>, E, R> =>
